// ==================== BRAND ====================
const BG        = '#0A1628';
const ACCENT    = '#C9A227';
const TEXT      = '#F5F7FA';
const MUTED     = '#8FA3BF';
const CLOUD     = 'yto9u5lp';
const FOLDER    = 'damu-linkedin';
const SIGNATURE = 'DAMU WINSTON';
const SIZE      = 1200;
// ===============================================

const norm  = (v) => String(v ?? '').trim();
const esc   = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&apos;');

function wrap(text, maxChars, maxLines) {
  const words = String(text).split(/\s+/).filter(Boolean);
  const lines = [];
  let cur = '';
  for (const w of words) {
    if (!cur) { cur = w; continue; }
    if ((cur + ' ' + w).length <= maxChars) cur += ' ' + w;
    else { lines.push(cur); cur = w; if (lines.length === maxLines) break; }
  }
  if (cur && lines.length < maxLines) lines.push(cur);
  if (lines.length === maxLines && words.join(' ').length > lines.join(' ').length) {
    lines[maxLines - 1] = lines[maxLines - 1].replace(/[.,;:]$/, '') + '...';
  }
  return lines;
}

function buildCard(hook, facts) {
  const hookLines = wrap(hook, 30, 4);
  const hookSize  = hookLines.length > 3 ? 62 : 72;
  const lh        = Math.round(hookSize * 1.22);

  let y = 210;
  let out = '';

  for (const l of hookLines) {
    out += `<text x="90" y="${y}" font-family="Georgia, 'Times New Roman', serif" font-size="${hookSize}" font-weight="700" fill="${TEXT}">${esc(l)}</text>`;
    y += lh;
  }

  y += 28;
  out += `<rect x="90" y="${y}" width="120" height="5" fill="${ACCENT}"/>`;
  y += 74;

  for (const f of facts.slice(0, 4)) {
    const fl = wrap(f, 46, 2);
    out += `<text x="90" y="${y}" font-family="Helvetica, Arial, sans-serif" font-size="36" fill="${ACCENT}">→</text>`;
    let fy = y;
    for (const line of fl) {
      out += `<text x="140" y="${fy}" font-family="Helvetica, Arial, sans-serif" font-size="34" fill="${MUTED}">${esc(line)}</text>`;
      fy += 44;
    }
    y = fy + 22;
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${SIZE}" height="${SIZE}" viewBox="0 0 ${SIZE} ${SIZE}">`
    + `<rect width="${SIZE}" height="${SIZE}" fill="${BG}"/>`
    + `<rect x="0" y="0" width="14" height="${SIZE}" fill="${ACCENT}"/>`
    + out
    + `<text x="90" y="${SIZE - 78}" font-family="Helvetica, Arial, sans-serif" font-size="26" letter-spacing="4" fill="${ACCENT}">${esc(SIGNATURE)}</text>`
    + `</svg>`;
}

const out = [];

for (const item of $input.all()) {
  const r        = (item.json && item.json.body && typeof item.json.body === 'object') ? item.json.body : item.json;
  const postId   = norm(r.postId || r.Post_ID);
  const text     = norm(r.postText || r.Post_Text);
  const source   = norm(r.sourceLink || r.Source_Link);
  const topic    = norm(r.storyTopic || r.Story_Topic);
  const vertical = norm(r.vertical || r.Vertical);
  const existing = norm(r.imageUrl || r.Image_URL);

  const publicId = `${FOLDER}/${postId}`;

  const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
  const hook  = lines[0] || topic || 'Damu Winston';

  // Arrow lines are the ideal card body. Short posts (Punchy) have none, so fall
  // back to the following sentences - a card is always better than no image.
  const arrowFacts = lines.filter(l => l.startsWith('→')).map(l => l.replace(/^→\s*/, '').trim());
  const proseFacts = lines.slice(1).filter(l => !l.startsWith('#') && !l.startsWith('→')).slice(0, 3);
  const facts = arrowFacts.length ? arrowFacts : proseFacts;

  const altText = `${hook}`.slice(0, 280);
  const base = { postId, publicId, altText, storyTopic: topic, vertical, sourceLink: source };

  if (existing.includes(`res.cloudinary.com/${CLOUD}/`)) {
    out.push({ json: { ...base, strategy: 'passthrough', imageSource: 'manual', finalUrl: existing } });
    continue;
  }

  if (/^https?:\/\//i.test(existing)) {
    out.push({ json: { ...base, strategy: 'upload', imageSource: 'manual_rehosted', file: existing } });
    continue;
  }

  if (facts.length >= 1) {
    const svg = buildCard(hook, facts);
    const b64 = Buffer.from(svg, 'utf8').toString('base64');
    out.push({ json: { ...base, strategy: 'upload', imageSource: 'branded_card', file: `data:image/svg+xml;base64,${b64}` } });
    continue;
  }

  const aiPrompt = `Editorial illustration for a senior-executive LinkedIn post about: ${topic || hook}. `
    + `Theme: ${vertical || 'capital markets and AI infrastructure'}. `
    + `Style: restrained corporate abstract, deep navy and gold palette, geometric, no text, no logos, no people's faces.`;

  out.push({ json: { ...base, strategy: 'ai', imageSource: 'ai_generated', aiPrompt } });
}

return out;

// Handles both the HTTP shape (JSON b64_json/url) and a binary shape, so it
// keeps working if the node is ever swapped again.
const planned = $('Choose Image Strategy').all().map(i => i.json).filter(p => p.strategy === 'ai');
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const base = planned[i] ?? {};
  let file = '';

  try {
    const binKeys = Object.keys(inputs[i].binary ?? {});
    if (binKeys.length) {
      const key = binKeys.includes('data') ? 'data' : binKeys[0];
      const buf = await this.helpers.getBinaryDataBuffer(i, key);
      const mime = inputs[i].binary[key].mimeType || 'image/png';
      file = `data:${mime};base64,${buf.toString('base64')}`;
    } else {
      const d = inputs[i].json?.data?.[0] ?? {};
      if (d.b64_json) file = `data:image/png;base64,${d.b64_json}`;
      else if (d.url) file = d.url;
    }
  } catch (e) {
    console.log('AI image conversion failed: ' + e.message);
  }

  if (!file) continue;
  out.push({ json: { ...base, file, strategy: 'upload', imageSource: 'ai_generated' } });
}

return out;

const CLOUD = 'yto9u5lp';

const planned = $('Choose Image Strategy').all().map(i => i.json);
const byId = {};
for (const p of planned) byId[p.postId] = p;

// SVG cards must be rasterised: Buffer reads image dimensions at publish time
// and LinkedIn will not accept an SVG.
const deliver = (pid, source) => {
  const raster = source === 'branded_card' ? 'png' : 'jpg';
  return `https://res.cloudinary.com/${CLOUD}/image/upload/f_${raster},q_auto:good,w_1200,h_1200,c_fit/${pid}.${raster}`;
};

const results = {};
const inputs = $input.all();

for (let idx = 0; idx < inputs.length; idx++) {
  const j = inputs[idx].json ?? {};

  if (j.strategy === 'passthrough' && j.finalUrl) {
    results[j.postId] = { postId: j.postId, imageUrl: j.finalUrl, imageSource: j.imageSource, altText: j.altText ?? '' };
    continue;
  }

  const pid = String(j.public_id ?? '');
  const postId = pid.includes('/') ? pid.split('/').pop() : (j.postId || planned[idx]?.postId || '');
  const plan = byId[postId] ?? planned[idx] ?? {};

  if (j.secure_url) {
    results[postId] = {
      postId,
      imageUrl: deliver(pid, plan.imageSource ?? 'uploaded'),
      imageSource: plan.imageSource ?? 'uploaded',
      altText: plan.altText ?? '',
    };
  } else if (postId) {
    results[postId] = {
      postId,
      imageUrl: '',
      imageSource: 'none',
      altText: plan.altText ?? '',
      attempted: plan.imageSource ?? '',
      error: j?.error?.message ?? j?.error ?? j?.message ?? 'Cloudinary upload returned no secure_url',
    };
  }
}

for (const p of planned) {
  if (!results[p.postId]) {
    results[p.postId] = { postId: p.postId, imageUrl: '', imageSource: 'none', altText: p.altText ?? '', attempted: p.imageSource ?? '' };
  }
}

const out = Object.values(results);
console.log(out.map(r => `${r.postId}: ${r.imageSource}${r.error ? ' | ' + r.error : ''} ${r.imageUrl || '(text-only)'}`).join('\n'));
return out.map(json => ({ json }));
